style.css:
/* Shanks Animekai Theme */

/* Top bar */
header {
  background-color: #1a1a1a !important; /* dark */
  color: #d4af37 !important;            /* gold */
  border-bottom: 2px solid #b22222 !important; /* red */
}

/* Buttons */
button {
  background-color: #b22222 !important; /* red */
  color: #ffffff !important;            /* white */
  border: 1px solid #d4af37 !important; /* gold */
}
button:hover {
  background-color: #d4af37 !important; /* gold */
  color: #1a1a1a !important;            /* dark */
}

/* Links */
a {
  color: #b22222 !important; /* red */
}
a:hover {
  color: #d4af37 !important; /* gold */
}
